def decode(s):
    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        count = int(s[start:i]) if i > start else 1
        result.append(char * count)

    return "".join(result)
